#!/usr/bin/env node

import path from 'node:path';
import fs from 'node:fs';
import { BASE_BIN_NAME, BIN_NAME_WITH_OS_ARCH, DIST_DIR } from './lib';

function cleanDist() {
  const binaries = fs.readdirSync(DIST_DIR);

  console.log(
    `Cleaning up ${DIST_DIR} directory from unused files and renaming the correct one...`
  );

  let ok = false;

  for (const file of binaries.values()) {
    if (!file.startsWith(BASE_BIN_NAME)) continue;
    if (!file.startsWith(BIN_NAME_WITH_OS_ARCH))
      fs.rmSync(path.join(DIST_DIR, file));
    else ok = true;
  }

  if (!ok) throw new Error("Can't find executable file.");
}

try {
  if (process.env.INIT_CWD === process.cwd()) process.exit();

  cleanDist();
} catch (e) {
  console.log("tengo-tester postinstall failed: " + e)
}
